const output = $input.first().json;

// Extract the AI response text from the Gemini node
let text = output.content?.parts?.[0]?.text;

if (!text) {
  throw new Error("AI response text was not found. Check the Gemini node output.");
}

// Remove Markdown code fences if the model included them
text = text
  .replace(/^```(?:json)?\s*/i, "")
  .replace(/\s*```$/, "")
  .trim();

// Parse the JSON string into an object
let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error(
    "Could not parse the AI response as JSON. Check whether Gemini returned valid, complete JSON. Response: " +
    text
  );
}

// Validate the required fields
const requiredFields = [
  "customer_response",
  "lead_status",
  "lead_score",
  "qualification_reason",
  "purchase_intent",
  "next_action"
];

for (const field of requiredFields) {
  if (parsed[field] === undefined || parsed[field] === null) {
    throw new Error(`Missing required AI output field: ${field}`);
  }
}

// Normalize the lead status
const leadStatus = String(parsed.lead_status).toUpperCase();

if (!["HOT", "COLD"].includes(leadStatus)) {
  throw new Error(`Invalid lead status: ${parsed.lead_status}`);
}

// Return separate fields for easy mapping
return [
  {
    json: {
      customer_response: parsed.customer_response,
      lead_status: leadStatus,
      lead_score: Number(parsed.lead_score),
      qualification_reason: parsed.qualification_reason,
      purchase_intent: parsed.purchase_intent,
      next_action: parsed.next_action
    }
  }
];
